module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
// Parameter declaration
parameter size = 4;
// Internal wires and registers
wire [3:0] mul_a_ext, mul_b_ext;
wire [7:0] partial_product[3:0];
reg [7:0] register[0:1][0:3];
reg [7:0] sum_tmp1, sum_tmp2;
// Combinational logic for extending inputs
assign mul_a_ext = {{size{1'b0}}, mul_a};
assign mul_b_ext = {{size{1'b0}}, mul_b};
// Generate partial products
generate
    genvar i;
    for(i = 0; i < size; i = i + 1) begin : gen_partial_products
        assign partial_product[i] = (mul_b_ext[i]) ? (mul_a_ext << i) : 'd0;
    end
endgenerate
// Sequential logic for pipelining stages
integer j;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        for(j = 0; j < 2; j = j + 1) begin
            register[j][0] <= 8'd0;
            register[j][1] <= 8'd0;
            register[j][2] <= 8'd0;
            register[j][3] <= 8'd0;
        end
    end else begin
        register[0][0] <= partial_product[0];
        register[0][1] <= partial_product[1];
        register[0][2] <= partial_product[2];
        register[0][3] <= partial_product[3];

        register[1][0] <= register[0][0] + register[0][1];
        register[1][1] <= register[0][2] + register[0][3];
        register[1][2] <= 8'd0;
        register[1][3] <= 8'd0;
    end
end
// Final product calculation
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        sum_tmp1 <= 8'd0;
        sum_tmp2 <= 8'd0;
    end else begin
        sum_tmp1 <= register[1][0];
        sum_tmp2 <= register[1][1];
    end
end
// Output assignment
assign mul_out = sum_tmp1 + sum_tmp2;
endmodule
